    total_sharpeners = 18
    total_cost = 100

    # Iterate through possible numbers of white sharpeners (w)
    for w in range(1, total_sharpeners):
        b = total_sharpeners - w  # Calculate brown sharpeners
        # The price of brown sharpener (p) must satisfy: w*(p+1) + b*p = 100
        # Simplify to: p*(w + b) + w = 100 => p*18 + w = 100 => p = (100 - w)/18
        p = (100 - w) / 18
        # Check if p is an integer and positive
        if p.is_integer() and p > 0:
            # Check if the total cost matches
            if w * (p + 1) + b * p == total_cost:
